		try {
			return executor.submit(() -> {
				try {
					deadline.checkActive();
					T value = count.call();
					deadline.checkActive();
					return value;
				} finally {
					inFlightCounts.release();
				}
			});
		} catch (RuntimeException e) {
			inFlightCounts.release();
			throw e;
		}
